import{_ as s,O as a,o as i,c as r,a as n,i as o,f as c}from"./chunks/framework.fmIt2z2h.js";const _=JSON.parse('{"title":"D.15　博弈、合作、信号、承诺与实施","description":"","frontmatter":{"title":"D.15　博弈、合作、信号、承诺与实施","xkChars":683,"xkLessons":{"D.15":{"title":"D.15　博弈、合作、信号、承诺与实施","lead":"一个规则能使人如实报告，不等于执行者会正确实施，也不等于未列入模型的人不承担代价。博弈分析的价值取决于行动、信息、资源和评价边界是否写清，不能把模型允许的动作当作现实全部可能。","explanation":["原文定位：第4753—4768行；原文锚点 section-d-15；短引文：‘机制保证必须注明允许动作集合。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","博弈表示先确定谁在何时行动、知道什么、实际能选什么、会产生何种结果以及如何评价。进入玩家集合不等于拥有所有相关人的代表权，未列为玩家的人也可能承担成本并拥有权利。模型中的控制节点和规范上应考虑的人不是同一名单，不能因某人没主动决策便将其损害从评价中删除。","第三方若能够改变许可或资源，应在相应因果行动模型中出现；若暂没有控制节点，仍须在规范分配中保留其地位。缺失一个执行者或资源约束，可能改变均衡与实施结果。补入后要重新求解相关问题，不能仅在旧模型外加一句有现实复杂性，却继续使用原结论覆盖新范围。","均衡存在、选择哪一个、是否实际到达、动态是否稳定、效率与正当性是六个不同问题。有纳什均衡只表明在所给策略与信念条件下没有单方更优偏离，不保证参与者能找到它，更不证明它最有效或最公平。多个均衡也不是模型自动选出历史实际结果，选择与学习过程需另外说明。","重复互动可使未来后果支持合作，也可能因误报、短期激励和失控惩罚破坏合作。对未来足够重视只是一些模型中的条件，真实关系还涉及监测误差、退出、补救和权力。不能把惩罚越严越合作写成普遍规律，更不能将理论中的惩罚策略当成现实实施许可。","高成本信号要有区分力，需看不同类型的激励是否不同、能否承担成本以及接收者怎样解释。若两种类型的净收益都促使它们发相同信号，成本虽高仍不能分辨；若弱势类型根本无力承担，信号又可能筛掉能力而非诚意。代价本身不是可信或真诚的充分证据。","承诺分为宣告、未来有理由履约、到时实际能履约。说会做不保证激励一致，愿意做也可能缺资源和权限。威慑旨在阻止某行动，要求撤回已做行动是不同任务；强硬自述不是有效性的证据，且对方遵守后威胁是否停止也影响激励与可信度。这里只分析条件，不提供强制他人的操作方案。","机制设计中的真实报告保证通常只针对明确的消息行动与收益结构。隐藏行动、监督者激励、共同经费、多个均衡和实际执行权限不会因报告真实而自动解决。报告阶段可以在原合同内成功，而实施阶段另失败，应修订具体节点，不笼统宣布全部理性模型无用。","规则准许的合法动作集合，与现实可采取的动作集合可能不同。在合法集合内没有获利偏离，只证明限制内的结论；若现实还有可获利违规，模型应作为可能事件进入e(t)并分析后果。把违规纳入预测不等于允许执行，规则禁止也不等于物理上不可能；两种集合必须分别标明。","二价拍卖的有限教学证明说明条件如何发挥作用。单物品、个人私人价值、准线性收益、无串谋及交易按规则执行下，固定他人的最高报价m。若自身价值v大于m，获胜收益v−m为正，如实报v能赢；压低到输只会放弃收益。若v小于m，输得0优于赢得负收益；若相等，赢输都为0。故如实报价弱占优，不保证严格唯一或保证卖方收入最高，更不覆盖串谋、拒付和第三方损害。","核心、Shapley分配与谈判解回答不同合作问题。联盟能否阻挡、按边际贡献怎样分、在给定威胁点与公理下如何谈判，是不同准则；没有任何一个名称自然产生唯一公平分配。规范选择、外部受损者与执行条件仍需公开。退出博弈解释也应具体：若行动信息价值无法合理表达，保留可用部分并换适合问题的方法，不把模型当必须完成的仪式。","十二个入口依次是表示边界、纳什协调、重复声誉、Spence等信号筛选、Harsanyi等不完全信息、Schelling承诺威慑、Olson与Buchanan公共选择、Hurwicz Maskin Myerson机制实施、合作分配、演化学习、网络多层互动，以及博弈解释退出条件。最强反方说只要现实能违规，机制保证就毫无意义；回应是原集合内保证仍可有价值，但不能跨出条件，扩展后需要重新分析而非伪称已解决。"],"distinctions":[{"leftTitle":"玩家","leftText":"模型中有决策节点的行动者。","rightTitle":"被代表与受影响者","rightText":"权利和成本范围可能更广，不能由玩家名单删除。"},{"leftTitle":"均衡存在","leftText":"所设条件下无单方获利偏离的组合存在。","rightTitle":"到达效率正当","rightText":"学习路径、总体结果与规范许可另需依据。"},{"leftTitle":"高成本信号","leftText":"发信号需要付代价。","rightTitle":"有区分力信号","rightText":"还需不同类型激励、承受能力和解释相匹配。"},{"leftTitle":"真实报告","leftText":"消息端在合同内无获利谎报。","rightTitle":"可靠实施","rightText":"隐藏动作、监督激励和资源权限仍要核。"},{"leftTitle":"合法动作集合","leftText":"规则允许选择的集合。","rightTitle":"现实动作集合","rightText":"实际可能包含违规，纳入模型不等允许实行。"}],"boundaries":["模型不产生对他人代表权，不因未列玩家就删除第三方权利和损失。","均衡、动态、效率与公平不互证，成本不直接认证信号真诚。","二价教学证明只限明确假设与单方消息偏离，不覆盖串谋拒付或执行破坏。","威慑惩罚等仅作概念分析，不授予现实强制或违规许可。","数字与游戏为作者教学构造，未开展真人博弈或实际交易。"],"questions":["均衡存在为什么不保证高效率？","二价证明为何是弱占优？","未列为玩家的人应如何保留？","补入监督和资源后为何要重解？"],"diagramPath":"/reading-assets/S-D-15/figures/section-d-15.png","caseLinks":[{"title":"真实理论原典：Vickrey的二价报价论证","href":"https://cramton.umd.edu/market-design-papers/vickrey-counterspeculation-auctions-and-competitive-sealed-tenders.pdf"}],"caseNotes":[{"title":"真实理论原典：Vickrey的二价报价论证","text":"Vickrey1961年原文第三节在印刷20—21页提出：最高报价者获分配而按第二高报价付价，并明确排除竞买者串谋，再比较低报与高报的得失。本讲只据这段原始理论核规则与条件，不把它称为现实拍卖实验或所有执行问题的解决；前述10、7、11等数字是另行构造。","sourceLabel":"William Vickrey，Journal of Finance16(1)，8—37，March1961，原刊扫描","sourceUrl":"https://cramton.umd.edu/market-design-papers/vickrey-counterspeculation-auctions-and-competitive-sealed-tenders.pdf","sourceLocator":"印刷pp20—21，§III第二段自Since it has been shown…至p21首段unprofitable transaction结尾；PDF第14—15页","boundary":"限定理论段落，未复核全篇附录、多物品扩展或现实执行；报告端单方激励不自动覆盖违规串谋、支付资源和第三方损失。","href":"https://cramton.umd.edu/market-design-papers/vickrey-counterspeculation-auctions-and-competitive-sealed-tenders.pdf"}],"sourceRefs":[{"section":"D.15","start_line":4753,"end_line":4768,"startLine":4753,"endLine":4768}],"outputId":"section-d-15","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["列行动节点信息实际选择结果与评价，单独列未当玩家但受影响者。","分别问均衡存在选择到达稳定效率正当，不由一个结果代付六问。","核重复互动误差、信号类型激励及承诺未来理由和能力。","区分报告与隐藏执行、监督、经费、第三方损害；标合法与现实动作集合。","补入新节点资源后重解，保留原保证原范围，实际违规入e(t)但不授权。"],"teachingExamples":[{"title":"数学教学构造：两个均衡，不同效率","text":"两个玩家各选A或B，同选A得(4,4)，同选B得(2,2)，不同选得(0,0)。AA与BB都是纯策略纳什均衡，因为单方改选都会降到0；但AA帕累托优于BB。存在均衡不解决选哪一个、怎样到达以及公平理由。","assumptions":"完全信息同时行动、收益仅按表确定。","boundary":"不是现实组织福利测量，也未提出必然收敛动态。"},{"title":"数学教学构造：二价规则的有限真实报告","text":"设本人价值10、其他人最高报价7；如实报10获胜付7，收益3。报6输得0，报12仍赢付7得3；如他人最高报价11，如实输得0，夸报12赢却得−1。一般证明见正文v与m三种情况，说明弱占优而不是每次严格唯一最优。","assumptions":"单物品、私人价值准线性、无串谋、可支付且规则执行，固定他人报价。","boundary":"不为真实竞拍给出报价建议，不保证所有机制目标或第三方福利。"},{"title":"原文教学例展开：报告有效、监督失败","text":"假想需求规则在规定消息集合内实现真实报告，但监督者在放任违规时自己获益，且不会受有效核查。需求报告可保留其有限保证，实施可靠性仍不成立。修订需把监督者动作、收益、权限和资源纳入，而非认为报表真实就完成整条链。","assumptions":"纯逻辑设定，未设计现实作弊或提供规避方法。","boundary":"不具体教授违规；真实报告保证须由实际机制证明，不能凭假想直接宣称。"},{"title":"数学教学构造：同样有代价仍不区分","text":"设两种类型发信号都得6单位收益、付4单位成本，不发收益0；两类净收益均2，因而都愿意发。信号有成本但在此模型中不分类型。若改变成本差异，还须重新核激励和接收者解释。","assumptions":"收益成本全为构造，无真实类型评判。","boundary":"不把人分为道德高低类型，不推断现实善意。"}],"counterexamples":[{"identity":"source_counterexample","text":"机制让人说真话，所以监督者不会违规、第三方也不会受损。","effect":"消息保证不覆盖隐藏执行监督激励和外部损害。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"规则禁止某动作，因此现实中不会发生，无须入模型。","effect":"合法与实际可行不同；可能违规可进入e(t)而不获得执行许可。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"两个类型都付了高成本，所以信号一定能区分类型。","effect":"相同净激励可产生混同，成本本身不足。","sourceIds":["theory"]}],"questionAnswers":[{"question":"均衡存在为什么不保证高效率？","answer":"协调例AA和BB均无单方获利偏离，BB却被AA帕累托支配。","basis":"本节原文及上述公开推导"},{"question":"二价证明为何是弱占优？","answer":"部分偏离仍赢付同样价格或仍输，收益可能相等，真实报价不必严格唯一。","basis":"本节原文及上述公开推导"},{"question":"未列为玩家的人应如何保留？","answer":"若有控制节点纳入因果模型，即使无节点仍保留其成本和权利评价。","basis":"本节原文及上述公开推导"},{"question":"补入监督和资源后为何要重解？","answer":"动作收益可行性与信息结构改变，旧均衡和保证未必适用于扩展模型。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-15/figures/section-d-15.png","alt":"行动信息选择先定，玩家≠全部受影响者；均衡存在／选择，到达／稳定，效率／正当分开；信号核类型激励，承诺核未来理由，也核实际履约能力；真实报告有限保证，隐藏执行监督，经费权限另核；合法与现实动作集合，不能混成同一个，违规入模型不授权；补节点与资源后重解，保留旧保证原范围，分配准则不等唯一公平。作者依D.15绘制；博弈数值纯教学，未实施竞拍、惩罚或任何违规动作。","caption":"作者依D.15绘制；博弈数值纯教学，未实施竞拍、惩罚或任何违规动作。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换合法与现实动作、监督者激励及资源，检验原保证是否仍适用。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"原始理论给出明确规则与无串谋条件，适合示范保证范围；教学证明与原典阅读各自标明，不冒称实证。"},"openQuestions":["未取得15.01—15.12全部原研究；未做真实机制实施或福利评估。","Vickrey只核指定理论段，未复算全篇附录及多物品扩展。"],"taskId":"S-D-15","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4753—4768行；每节精确范围见sourceRefs","claim_support":["D.15：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"vickrey1961","title":"Counterspeculation, Auctions, and Competitive Sealed Tenders","url":"https://cramton.umd.edu/market-design-papers/vickrey-counterspeculation-auctions-and-competitive-sealed-tenders.pdf","source_type":"primary","version_or_date":"March1961，Journal of Finance16(1)，8—37","locator":"印刷pp20—21，§III第二段至跨页首段结尾（PDF14—15页）","claim_support":["最高报价者按第二高报价付价；排除串谋条件与低报高报论证"],"limits":["限单物品理论段，不是实际实验，未核全篇附录或实施，原保证不能越出假设。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-15/lecture.md","sourcesPath":"/reading-assets/S-D-15/sources.json","sourceSlicePath":"/reading-assets/S-D-15/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-15/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-15.md","filePath":"theory/appendix-d/d-15.md"}'),d={name:"theory/appendix-d/d-15.md"};function l(p,e,u,m,h,f){const t=a("SectionLesson");return i(),r("div",null,[e[0]||(e[0]=n('<div class="theory-source"><h1 id="section-d-15" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.15</span><span class="xk-num__gap">　</span></span>博弈、合作、信号、承诺与实施 <a class="header-anchor" href="#section-d-15" aria-label="Permalink to &quot;D.15　博弈、合作、信号、承诺与实施 {#section-d-15}&quot;">​</a></h1><p>正文连接：§10.5；§11.3、11.7；§12；§14。研究入口：15.01—15.12。</p><p>博弈表示先确定实际行动节点、信息、可行选择、结果及评价。进入玩家集合，不等于拥有全部代表权；未被列为玩家的人，也可能承担成本并拥有权利。第三方若能改变许可或资源，应在因果模型中出现；若暂无控制节点，仍不能从规范分配中删除。</p><p>均衡存在、均衡选择、实际到达、动态稳定、效率和正当性各需依据。重复互动可以支持合作，也可能因为误报、短时激励或惩罚失控而破坏合作。一个高成本信号只有在不同类型的选择激励、成本可承担性和接收者解释相匹配时，才可能具有区分力。</p><p>承诺须分宣告、未来有理由履约和届时实际能履约。威慑与要求撤回既有行动不同，二者均不能仅靠强硬自述证明奏效；遵守后威胁能够停止的保证也有作用。机制设计中的真实报告，不自动解决隐藏行动、监督者激励、多个均衡或执行权限。</p><p>教学例：规则让成员如实报出需求，却把监督交给会因违规受益的人。报告端可能有效，实施端仍失败。要修订的是具体行动和激励链，而非笼统宣称理性模型无用。核心、Shapley分配与谈判解回答不同合作问题，也不自然产生唯一公平分配。实际违规进入e(t)，并不因被模拟而获准执行。</p><p>机制保证必须注明允许动作集合。规则规定的合法动作与现实能够采取的动作可能不同；在前一集合内无利可图的偏离，不证明后一集合的违规已经没有吸引力。真实报告的保证也不自动覆盖隐藏执行、共享经费或第三方损失。补入执行者和资源约束后，应重新求解相应机制，保留原保证在原条件中的有效范围。</p><p>专题定位：15.01 博弈表示的边界；15.02 纳什均衡与协调困境；15.03 重复博弈、声誉与合作；15.04 信号、筛选与廉价沟通：Spence 等；15.05 不完全信息、信念与猜疑链：Harsanyi 等；15.06 承诺、威慑与讨价还价：Schelling 等；15.07 公共选择、搭便车与集体行动：Olson、Buchanan；15.08 机制设计与实施：Hurwicz、Maskin、Myerson；15.09 合作博弈、联盟与分配；15.10 演化博弈与学习动态；15.11 网络博弈与多层互动；15.12 博弈解释的退出条件。</p></div>',1)),o(t,{section:"D.15"}),e[1]||(e[1]=c("div",{class:"theory-source"},null,-1))])}const g=s(d,[["render",l]]);export{_ as __pageData,g as default};
